CREATE TABLE matches (id INTEGER PRIMARY KEY AUTOINCREMENT, home TEXT NOT NULL, away TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'LIVE', home_score INTEGER NOT NULL DEFAULT 0, away_score INTEGER NOT NULL DEFAULT 0);
CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT, match_id INTEGER NOT NULL REFERENCES matches(id), minute INTEGER NOT NULL, type TEXT NOT NULL, team TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL);
